const EXPECTED_RGB_BYTE_LENGTH = PIX_GRID_NEON_MARQUEE_FRAME_CELL_COUNT * 3
let decodedFrames: readonly Uint8Array[] | null = null

function decodeBase64Rgb(value: string): Uint8Array {
  const binary = atob(value.replace(/\s+/g, ''))
  if (binary.length !== EXPECTED_RGB_BYTE_LENGTH) {
    throw new Error(`Invalid PixGrid neon marquee frame byte length ${binary.length}; expected ${EXPECTED_RGB_BYTE_LENGTH}.`)
  }
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
  return bytes
}

export function getPixGridNeonMarqueeFrames(): readonly Uint8Array[] {
  if (!decodedFrames) {
    decodedFrames = PIX_GRID_NEON_MARQUEE_FRAME_ORDER.map(frame => decodeBase64Rgb(ENCODED_RGB_BY_FRAME[frame.id]))
  }
  return decodedFrames
}

export interface PixGridNeonMarqueeSample {
  alpha: number
  role: PixGridPaletteRole
  color: readonly [number, number, number]
}

export function samplePixGridNeonMarqueeFrame(
  u: number,
  v: number,
  frameIndex: number,
): PixGridNeonMarqueeSample {
  if (u < 0 || u >= 1 || v < 0 || v >= 1) return { alpha: 0, role: 'primary', color: [0, 0, 0] }
  const frames = getPixGridNeonMarqueeFrames()
  const normalizedFrameIndex = ((Math.floor(frameIndex) % frames.length) + frames.length) % frames.length
  const x = Math.max(0, Math.min(PIX_GRID_NEON_MARQUEE_FRAME_WIDTH - 1, Math.floor(u * PIX_GRID_NEON_MARQUEE_FRAME_WIDTH)))
  const y = Math.max(0, Math.min(PIX_GRID_NEON_MARQUEE_FRAME_HEIGHT - 1, Math.floor(v * PIX_GRID_NEON_MARQUEE_FRAME_HEIGHT)))
  const offset = (y * PIX_GRID_NEON_MARQUEE_FRAME_WIDTH + x) * 3
  const frame = frames[normalizedFrameIndex]
  return { alpha: 1, role: 'primary', color: [frame[offset], frame[offset + 1], frame[offset + 2]] }
}
